16	ReplicatedMergeMutateTaskBase::PrepareResult MutateFromLogEntryTask::prepare()
17	{
18	    const String & source_part_name = entry.source_parts.at(0);
19	    const auto storage_settings_ptr = storage.getSettings();
20	    LOG_TRACE(log, "Executing log entry to mutate part {} to {}", source_part_name, entry.new_part_name);
21	
22	    MergeTreeData::DataPartPtr source_part = storage.getActiveContainingPart(source_part_name);
23	    if (!source_part)
24	    {
25	        LOG_DEBUG(log, "Source part {} for {} is not ready; will try to fetch it instead", source_part_name, entry.new_part_name);
26	        return PrepareResult{
27	            .prepared_successfully = false,
28	            .need_to_check_missing_part_in_fetch = true,
29	            .part_log_writer = {}
30	        };
31	    }
32	
33	    if (source_part->name != source_part_name)
34	    {
35	        LOG_WARNING(log,
36	            "Part {} is covered by {} but should be mutated to {}. "
37	            "Possibly the mutation of this part is not needed and will be skipped. "
38	            "This shouldn't happen often.",
39	            source_part_name, source_part->name, entry.new_part_name);
40	
41	        return PrepareResult{
42	            .prepared_successfully = false,
43	            .need_to_check_missing_part_in_fetch = true,
44	            .part_log_writer = {}
45	        };
46	    }
47	
48	    /// TODO - some better heuristic?
49	    size_t estimated_space_for_result = MergeTreeDataMergerMutator::estimateNeededDiskSpace({source_part});
50	
51	    if (entry.create_time + storage_settings_ptr->prefer_fetch_merged_part_time_threshold.totalSeconds() <= time(nullptr)
52	        && estimated_space_for_result >= storage_settings_ptr->prefer_fetch_merged_part_size_threshold)
53	    {
54	        /// If entry is old enough, and have enough size, and some replica has the desired part,
55	        /// then prefer fetching from replica.
56	        String replica = storage.findReplicaHavingPart(entry.new_part_name, true);    /// NOTE excessive ZK requests for same data later, may remove.
57	        if (!replica.empty())
58	        {
59	            LOG_DEBUG(log, "Prefer to fetch {} from replica {}", entry.new_part_name, replica);
60	            return PrepareResult{
61	                .prepared_successfully = false,
62	                .need_to_check_missing_part_in_fetch = true,
63	                .part_log_writer = {}
64	            };
65	        }
66	    }
67	
68	    /// In some use cases merging can be more expensive than fetching
69	    /// and it may be better to spread merges tasks across the replicas
70	    /// instead of doing exactly the same merge cluster-wise
71	
72	    if (storage.merge_strategy_picker.shouldMergeOnSingleReplica(entry))
73	    {
74	        std::optional<String> replica_to_execute_merge = storage.merge_strategy_picker.pickReplicaToExecuteMerge(entry);
75	        if (replica_to_execute_merge)
76	        {
77	            LOG_DEBUG(log,
78	                "Prefer fetching part {} from replica {} due to execute_merges_on_single_replica_time_threshold",
79	                entry.new_part_name, replica_to_execute_merge.value());
80	
81	            return PrepareResult{
82	                .prepared_successfully = false,
83	                .need_to_check_missing_part_in_fetch = true,
84	                .part_log_writer = {}
85	            };
86	
87	        }
88	    }
89	
90	    new_part_info = MergeTreePartInfo::fromPartName(entry.new_part_name, storage.format_version);
91	    commands = std::make_shared<MutationCommands>(storage.queue.getMutationCommands(source_part, new_part_info.mutation));
92	
93	    /// Once we mutate part, we must reserve space on the same disk, because mutations can possibly create hardlinks.
94	    /// Can throw an exception.
95	    reserved_space = storage.reserveSpace(estimated_space_for_result, source_part->data_part_storage);
96	
97	    table_lock_holder = storage.lockForShare(
98	            RWLockImpl::NO_QUERY, storage_settings_ptr->lock_acquire_timeout_for_background_operations);
99	    StorageMetadataPtr metadata_snapshot = storage.getInMemoryMetadataPtr();
100	
101	    transaction_ptr = std::make_unique<MergeTreeData::Transaction>(storage, NO_TRANSACTION_RAW);
102	
103	    future_mutated_part = std::make_shared<FutureMergedMutatedPart>();
104	    future_mutated_part->name = entry.new_part_name;
105	    future_mutated_part->uuid = entry.new_part_uuid;
106	    future_mutated_part->parts.push_back(source_part);
107	    future_mutated_part->part_info = new_part_info;
108	    future_mutated_part->updatePath(storage, reserved_space.get());
109	    future_mutated_part->type = source_part->getType();
110	
111	    if (storage_settings_ptr->allow_remote_fs_zero_copy_replication)
112	    {
113	        if (auto disk = reserved_space->getDisk(); disk->supportZeroCopyReplication())
114	        {
115	            String dummy;
116	            if (!storage.findReplicaHavingCoveringPart(entry.new_part_name, true, dummy).empty())
117	            {
118	                LOG_DEBUG(log, "Mutation of part {} finished by some other replica, will download mutated part", entry.new_part_name);
119	                return PrepareResult{
120	                    .prepared_successfully = false,
121	                    .need_to_check_missing_part_in_fetch = true,
122	                    .part_log_writer = {}
123	                };
124	            }
125	
126	            zero_copy_lock = storage.tryCreateZeroCopyExclusiveLock(entry.new_part_name, disk);
127	
128	            if (!zero_copy_lock)
129	            {
130	                LOG_DEBUG(log, "Mutation of part {} started by some other replica, will wait it and mutated merged part", entry.new_part_name);
131	                return PrepareResult{
132	                    .prepared_successfully = false,
133	                    .need_to_check_missing_part_in_fetch = false,
134	                    .part_log_writer = {}
135	                };
136	            }
137	        }
138	    }
139	
140	
141	    const Settings & settings = storage.getContext()->getSettingsRef();
142	    merge_mutate_entry = storage.getContext()->getMergeList().insert(
143	        storage.getStorageID(),
144	        future_mutated_part,
145	        settings);
146	
147	    stopwatch_ptr = std::make_unique<Stopwatch>();
148	
149	    fake_query_context = Context::createCopy(storage.getContext());
150	    fake_query_context->makeQueryContext();
151	    fake_query_context->setCurrentQueryId("");
152	
153	    mutate_task = storage.merger_mutator.mutatePartToTemporaryPart(
154	            future_mutated_part, metadata_snapshot, commands, merge_mutate_entry.get(),
155	            entry.create_time, fake_query_context, NO_TRANSACTION_PTR, reserved_space, table_lock_holder);
156	
157	    /// Adjust priority
158	    for (auto & item : future_mutated_part->parts)
159	        priority += item->getBytesOnDisk();
160	
161	    return {true, true, [this] (const ExecutionStatus & execution_status)
162	    {
163	        storage.writePartLog(
164	            PartLogElement::MUTATE_PART, execution_status, stopwatch_ptr->elapsed(),
165	            entry.new_part_name, new_part, future_mutated_part->parts, merge_mutate_entry.get());
166	    }};
167	}
