170	bool MutateFromLogEntryTask::finalize(ReplicatedMergeMutateTaskBase::PartLogWriter write_part_log)
171	{
172	    new_part = mutate_task->getFuture().get();
173	    auto builder = mutate_task->getBuilder();
174	
175	    if (!builder)
176	        builder = new_part->data_part_storage->getBuilder();
177	
178	    storage.renameTempPartAndReplace(new_part, *transaction_ptr, builder);
179	
180	    try
181	    {
182	        storage.checkPartChecksumsAndCommit(*transaction_ptr, new_part, mutate_task->getHardlinkedFiles());
183	    }
184	    catch (const Exception & e)
185	    {
186	        if (MergeTreeDataPartChecksums::isBadChecksumsErrorCode(e.code()))
187	        {
188	            transaction_ptr->rollback();
189	
190	            ProfileEvents::increment(ProfileEvents::DataAfterMutationDiffersFromReplica);
191	
192	            LOG_ERROR(log, "{}. Data after mutation is not byte-identical to data on another replicas. "
193	                           "We will download merged part from replica to force byte-identical result.", getCurrentExceptionMessage(false));
194	
195	            write_part_log(ExecutionStatus::fromCurrentException());
196	
197	            if (storage.getSettings()->detach_not_byte_identical_parts)
198	                storage.forgetPartAndMoveToDetached(std::move(new_part), "mutate-not-byte-identical");
199	            else
200	                storage.tryRemovePartImmediately(std::move(new_part));
201	
202	            /// No need to delete the part from ZK because we can be sure that the commit transaction
203	            /// didn't go through.
204	
205	            return false;
206	        }
207	
208	        throw;
209	    }
210	
211	    if (zero_copy_lock)
212	    {
213	        LOG_DEBUG(log, "Removing zero-copy lock");
214	        zero_copy_lock->lock->unlock();
215	    }
216	
217	    /** With `ZSESSIONEXPIRED` or `ZOPERATIONTIMEOUT`, we can inadvertently roll back local changes to the parts.
218	         * This is not a problem, because in this case the entry will remain in the queue, and we will try again.
219	         */
220	    storage.merge_selecting_task->schedule();
221	    ProfileEvents::increment(ProfileEvents::ReplicatedPartMutations);
222	    write_part_log({});
223	
224	    return true;
225	}
